import { getChampions, ledgerKey } from '../../ledger.mjs';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { buildGateTable, STAR_COUNT_WARN } from '../gate-contract.mjs';

const TAXONOMY_PATH = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../target-taxonomy.json');

/** Classes whose faintStructureGoal is outer_halo (finish subject_contrast gate relaxes to 2x for them). */
function outerHaloClasses() {
  try {
    const tax = JSON.parse(fs.readFileSync(TAXONOMY_PATH, 'utf-8'));
    return Object.entries(tax.categories || {}).filter(([, v]) => v?.traits?.faintStructureGoal === 'outer_halo').map(([k]) => k);
  } catch (e) { return []; }
}

/** WI-09: the one gate table of the prompt (rows resolved from the brief by gate-contract.buildGateTable). */
export function renderGateTable(brief) {
  const EMERGENCY = 'Relaxed to a warning when <=10 turns remain (emergency budget).';
  const ag = brief?.processingProfile?.aesthetic_gate;
  const aestheticBlocking = ag?.blocking === true && Number.isFinite(ag?.min_score) && !brief?.dataDescription?.starless && !brief?.dataDescription?.narrowband;
  // The finish handler keeps the critic ADVISORY unless the profile sets aesthetic_gate.blocking (WI-02); show the real status.
  const rows = buildGateTable(brief).filter((r) => r.status !== 'SKIPPED')
    .map((r) => (r.gate === 'aesthetic' && !aestheticBlocking ? { ...r, status: 'ADVISORY', relaxation: 'Advisory until aesthetic_gate.min_score is calibrated.' } : r));
  const lines = ['| gate | measured by | limit | status | relaxation |', '|---|---|---|---|---|'];
  for (const r of rows) {
    lines.push(`| ${r.gate} | ${r.tool} | ${r.predicateText} | ${r.status} | ${r.relaxation === EMERGENCY ? 'emergency' : r.relaxation} |`);
  }
  const halo = outerHaloClasses();
  lines.push('');
  lines.push('"emergency" = relaxed to a warning when 10 or fewer turns remain. Other rows never relax. WARNING rows never block finish.');
  if (halo.length) lines.push(`subject_contrast is 2x instead of 3x for classes whose faint-structure goal is outer_halo (${halo.join(', ')}); this class: ${brief?.target?.classification}. Compact galaxies use the relaxed tonal limit shown in the tonal_presence row.`);
  lines.push(`Star count below ${STAR_COUNT_WARN} warns (stars missing or over-reduced). Colour diversity of stars must stay above 0.05.`);
  return lines.join('\n');
}

